package com.utegear.service;

import com.utegear.dto.catalog.ProductDtos; import com.utegear.entity.Product; import com.utegear.entity.ProductStatus; import com.utegear.exception.ApiException; import com.utegear.repository.ProductRepository; import jakarta.persistence.criteria.Expression; import jakarta.persistence.criteria.Predicate; import java.math.BigDecimal; import java.util.ArrayList; import java.util.List; import java.util.Set; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ProductCatalogService {
 private static final Set<String> SORTS=Set.of("name","effectivePrice","createdAt"); private final ProductRepository repository; public ProductCatalogService(ProductRepository repository){this.repository=repository;}
 @Transactional(readOnly=true) public ProductDtos.ProductPage search(String q,Long categoryId,Long brandId,BigDecimal min,BigDecimal max,int page,int size,String sort){if(page<0||size<1||size>100||min!=null&&min.signum()<0||max!=null&&(max.signum()<0||min!=null&&max.compareTo(min)<0))throw invalid();String[] parts=sort.split(",",-1);if(parts.length!=2||!SORTS.contains(parts[0])||!(parts[1].equals("asc")||parts[1].equals("desc")))throw invalid();Specification<Product> spec=(root,query,cb)->{List<Predicate> ps=new ArrayList<>();ps.add(cb.equal(root.get("status"),ProductStatus.ACTIVE));if(q!=null&&!q.isBlank())ps.add(cb.like(cb.lower(root.get("name")),"%"+q.trim().toLowerCase()+"%"));if(categoryId!=null)ps.add(cb.equal(root.get("category").get("id"),categoryId));if(brandId!=null)ps.add(cb.equal(root.get("brand").get("id"),brandId));Expression<BigDecimal> price=cb.<BigDecimal>coalesce().value(root.get("salePrice")).value(root.get("basePrice"));if(min!=null)ps.add(cb.greaterThanOrEqualTo(price,min));if(max!=null)ps.add(cb.lessThanOrEqualTo(price,max));if(query.getResultType()!=Long.class){Expression<?> order=parts[0].equals("effectivePrice")?price:root.get(parts[0]);query.orderBy(parts[1].equals("asc")?cb.asc(order):cb.desc(order));}return cb.and(ps.toArray(Predicate[]::new));};return ProductDtos.ProductPage.from(repository.findAll(spec,PageRequest.of(page,size)));}
 @Transactional(readOnly=true) public ProductDtos.Detail detail(Long id){return repository.findByIdAndStatus(id,ProductStatus.ACTIVE).map(ProductDtos.Detail::from).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"PRODUCT_NOT_FOUND","Không tìm thấy sản phẩm"));}
 private ApiException invalid(){return new ApiException(HttpStatus.BAD_REQUEST,"INVALID_FILTER","Bộ lọc không hợp lệ");}
}
